public int Search(int[] nums, int target) {
    int lo = 0, hi = nums.Length - 1;          // если target есть, он в [lo..hi]
    while (lo <= hi) {                         // интервал не пуст
        int mid = lo + (hi - lo) / 2;          // без переполнения
        if (nums[mid] == target) return mid;
        if (nums[mid] < target) lo = mid + 1;  // nums[0..mid] < target
        else hi = mid - 1;                     // nums[mid..] > target
    }
    return -1;                                 // lo > hi: кандидатов нет
}

