// a = [1, 3, 3, 3, 8]
// LowerBound(a, 3) = 1 — первый a[i] >= 3
// UpperBound(a, 3) = 4 — первый a[i] > 3
// тройка встречается 4 - 1 = 3 раза, последняя — на индексе 3
int LowerBound(int[] a, int x) {
    int lo = 0, hi = a.Length;              // a[0..lo) < x <= a[hi..n)
    while (lo < hi) {                       // полоса [lo, hi) не пуста
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;       // mid — среди меньших
        else hi = mid;                      // mid — среди не меньших
    }
    return lo;
}

