int[] SearchRange(int[] a, int x) {
    int first = LowerBound(a, x);
    if (first == a.Length || a[first] != x) return new[] { -1, -1 };
    return new[] { first, UpperBound(a, x) - 1 };
}

int FindPeak(int[] a) {                      // соседи различны
    int lo = 0, hi = a.Length - 1;           // пик есть в [lo..hi]
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;        // mid < hi: a[mid + 1] существует
        if (a[mid] < a[mid + 1]) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

